// Prepares the Android project generated by "flutter create".
// Adds the INTERNET permission so images from the web also load in
// release builds (debug builds already allow it). Safe to run many times.
import 'dart:io';

void main() {
  final file = File('android/app/src/main/AndroidManifest.xml');
  if (!file.existsSync()) {
    stdout.writeln('  Android folder not found. Run "flutter create ." first.');
    return;
  }
  final xml = file.readAsStringSync();
  if (xml.contains('android.permission.INTERNET')) {
    stdout.writeln('  Internet permission is already set.');
    return;
  }
  final updated = xml.replaceFirstMapped(
    RegExp(r'<manifest[^>]*>'),
    (m) => '${m[0]}\n    <uses-permission android:name="android.permission.INTERNET"/>',
  );
  file.writeAsStringSync(updated);
  stdout.writeln('  Added internet permission (needed for images from the web).');
}
